// Modified by T02: 全部映射改为从 KyrgyzAlphabet 派生，本文件不再持有任何字符字面量
package com.example.kyrgyzkeyboard.utils

import com.example.kyrgyzkeyboard.keyboard.KyrgyzAlphabet

/**
 * 柯尔克孜语字符工具（纯函数，无副作用）。
 *
 * 字符集与键位映射**全部来自 [KyrgyzAlphabet]**（单一真源），本对象只做查询与归一化，
 * 不重复声明任何码位。
 *
 * 依据：
 * - GB 21669-2008《信息技术 维吾尔文、哈萨克文、柯尔克孜文编码字符集》
 * - GB/T 31917-2015《信息技术 柯尔克孜文通用键盘字母数字区布局》
 * - GB/T 31921-2015《信息技术 基于数字键盘的柯尔克孜文字母布局》
 */
object KyrgyzCharacterUtils {

    /** 30 个标准字母（附录 A 表 A.1）。 */
    val ALL_LETTERS: Set<String> = KyrgyzAlphabet.LETTERS.toSet()

    /** 8 个元音。 */
    val VOWELS: Set<String> = KyrgyzAlphabet.VOWELS

    /** 22 个辅音 = 全集 − 元音。 */
    val CONSONANTS: Set<String> = KyrgyzAlphabet.CONSONANTS

    /** 附加符号（fatha / kasra / damma / shadda）。 */
    val DIACRITICS: Set<String> = KyrgyzAlphabet.DIACRITICS.toSet()

    /** GB 标准标点符号（附录 C，7 个）。 */
    val PUNCTUATION: Set<String> = KyrgyzAlphabet.PUNCTUATION.toSet()

    /**
     * QWERTY 键位 -> 输出字符（表 2 第 1 层）。
     * 直接引用 [KyrgyzAlphabet.LAYER1]，与屏幕布局同源，不再独立维护。
     */
    private val QWERTY_TO_KYRGYZ: Map<Char, String> = KyrgyzAlphabet.LAYER1

    /**
     * QWERTY Shift 层键位映射（表 2 第 2 层）。
     * 未列出的键回落到第 1 层（见 [getKeyboardMapping]）。
     */
    private val QWERTY_TO_KYRGYZ_SHIFT: Map<Char, String> = KyrgyzAlphabet.LAYER2

    /**
     * 数字键盘键位映射（GB/T 31921-2015 表 1 标准）。
     * 数字键 -> 该键上的字符列表。
     */
    val DIGITAL_TO_KYRGYZ: Map<Char, List<String>> = mapOf(
        '1' to listOf(
            KyrgyzAlphabet.PERIOD, KyrgyzAlphabet.COMMA, KyrgyzAlphabet.SEMICOLON,
            KyrgyzAlphabet.QUESTION, "!"
        ),
        '2' to listOf(KyrgyzAlphabet.ALEF, KyrgyzAlphabet.BE, KyrgyzAlphabet.CHE, KyrgyzAlphabet.AIN),
        '3' to listOf(KyrgyzAlphabet.DAL, KyrgyzAlphabet.E, KyrgyzAlphabet.HAMZA, KyrgyzAlphabet.FEH),
        '4' to listOf(KyrgyzAlphabet.GAF, KyrgyzAlphabet.HAH, KyrgyzAlphabet.YI),
        '5' to listOf(KyrgyzAlphabet.JEEM, KyrgyzAlphabet.KAF, KyrgyzAlphabet.LAM),
        '6' to listOf(KyrgyzAlphabet.MEEM, KyrgyzAlphabet.NUN, KyrgyzAlphabet.WAU, KyrgyzAlphabet.NG),
        '7' to listOf(KyrgyzAlphabet.PE, KyrgyzAlphabet.QAF, KyrgyzAlphabet.RE, KyrgyzAlphabet.SEEN),
        '8' to listOf(KyrgyzAlphabet.TE, KyrgyzAlphabet.UU, KyrgyzAlphabet.OE, KyrgyzAlphabet.UE),
        '9' to listOf(KyrgyzAlphabet.VE, KyrgyzAlphabet.SHEEN, KyrgyzAlphabet.YE, KyrgyzAlphabet.ZAIN),
        '0' to listOf(
            " ", KyrgyzAlphabet.TATWEEL, KyrgyzAlphabet.ELLIPSIS,
            KyrgyzAlphabet.GUILLEMET_LEFT, KyrgyzAlphabet.GUILLEMET_RIGHT
        )
    )

    /** 单字符是否属于柯尔克孜字母表。 */
    fun isKyrgyzLetter(char: Char): Boolean =
        ALL_LETTERS.contains(char.toString())

    /** 单字符是否为元音。 */
    fun isVowel(char: Char): Boolean =
        VOWELS.contains(char.toString())

    /**
     * 阿拉伯写法文本规范化：
     * 1. 去除阿拉伯 tatweel（U+0640）拉长符
     * 2. 折叠连续空白
     * 3. 波斯 ي(U+06CC) 折叠为标准 ي(U+064A)
     *
     * 归一化后的输出只会包含标准字母、标点或空白——不再产生标准集外的码位。
     */
    fun normalizeArabicText(text: String): String {
        if (text.isEmpty()) return text
        val sb = StringBuilder(text.length)
        var lastWasSpace = false
        for (raw in text) {
            val ch = when (raw) {
                KyrgyzAlphabet.TATWEEL[0] -> continue                // 忽略 tatweel
                KyrgyzAlphabet.FARSI_YEH[0] -> KyrgyzAlphabet.YE[0]   // 波斯 ي -> 标准 ي
                else -> raw
            }
            if (ch.isWhitespace()) {
                if (!lastWasSpace) sb.append(' ')
                lastWasSpace = true
            } else {
                sb.append(ch)
                lastWasSpace = false
            }
        }
        return sb.toString().trim()
    }

    /**
     * 硬件键盘按键 -> 柯尔克孜字母。返回 null 表示无映射。
     * @param isShift 是否按下 Shift 键（使用第 2 层映射，未规定时回落到第 1 层）
     */
    fun getKeyboardMapping(qwertyChar: Char, isShift: Boolean = false): String? {
        val lower = qwertyChar.lowercaseChar()
        return if (isShift) {
            QWERTY_TO_KYRGYZ_SHIFT[lower] ?: QWERTY_TO_KYRGYZ[lower]
        } else {
            QWERTY_TO_KYRGYZ[lower]
        }
    }

    /**
     * 数字键盘按键 -> 柯尔克孜字母。
     * @param index 该键上的字符索引（0 为默认）
     */
    fun getDigitalMapping(digitalChar: Char, index: Int = 0): String? {
        val chars = DIGITAL_TO_KYRGYZ[digitalChar] ?: return null
        return if (index in chars.indices) chars[index] else chars[0]
    }

    /**
     * 获取数字键上的所有字符列表。
     */
    fun getDigitalChars(digitalChar: Char): List<String>? {
        return DIGITAL_TO_KYRGYZ[digitalChar]
    }
}
